// FlowLayoutPanelCompat::item_spacing: finite(incoming.width) and finite(incoming.height) and incoming.width >= 0 and
// incoming.height >= 0 and incoming.width <= 256 and incoming.height <= 256; else failure invalid_argument.
[[nodiscard]] constexpr bool admits_item_spacing(const Size incoming) noexcept {
    const bool result = __builtin_isfinite(incoming.width)
                     && __builtin_isfinite(incoming.height)
                     && (incoming.width >= 0)
                     && (incoming.height >= 0)
                     && (incoming.width <= 256)
                     && (incoming.height <= 256);
    return result;
}

